"""fxprovider 2.3.1, internal FX rate client (offline build: serves a fixed snapshot of the rates feed)."""
from dataclasses import dataclass

__version__ = "2.3.1"


@dataclass(frozen=True)
class Quote:
    pair: str
    rate: str      # decimal string, as served by the rates feed
    asof: str


class LiveRates:
    def eur_usd(self):
        return Quote("EUR/USD", "1.0842", "2026-11-06T16:00:00Z")
